# templated families (deterministic sample)
START = ["is it", "is it safe", "is it ok", "is it fine", "is it advisable", "would it be wise", "should I", "can I", "may I", "could I", "do you recommend that I", "would you advise me to", "am I able to"]
GO = ["to drive", "to go out", "to take a long trip", "to go on a long drive", "to take the car out", "to travel today", "to head out", "to take a road trip", "to drive to work", "to drive to the mall", "to use the car", "to keep driving", "to continue my drive", "to go on the highway", "to go for a long journey", "to drive far"]
COND = ["", "", "in this condition", "right now", "with these warnings", "today", "with the current faults", "given the car's state", "like this"]
SIG = ["the battery power", "the power", "the coolant flow", "the motor temperature", "the pack temperature", "the speed", "the state of charge", "the battery current"]
STT = ["negative", "zero", "high", "low", "rising", "dropping", "jumping around", "so different"]


SWAPS = [("car", "vehicle"), ("battery", "pack"), ("drive", "go"), ("trip", "journey"), ("charge", "charging"), ("fine", "ok"), ("safe", "okay"), ("energy", "power"), ("how far", "how many km"), ("yesterday", "the day before today"),
         ("hot", "warm"), ("problem", "issue"), ("recent", "latest"), ("lately", "recently"), ("a long", "a big"), ("show me", "tell me"), ("check", "look at"), ("summary", "overview"), ("tips", "advice"), ("use", "consume")]
LEAD = ["", "", "hey ", "please ", "can you tell me ", "I want to know ", "quick question: ", "so ", "uh "]


def augment(rows, rnd):
    out = {}
    for r, qs in rows.items():
        new = list(qs)
        for q in qs:
            v = q
            for a, b in SWAPS:
                if a in v.split() or f" {a} " in f" {v} ":
                    if rnd.random() < 0.5: v = (" " + v + " ").replace(f" {a} ", f" {b} ").strip()
            if v != q: new.append(v)
            if rnd.random() < 0.35: new.append((rnd.choice(LEAD[2:]) + q).strip())
        out[r] = list(dict.fromkeys(new))
    return out


def build():
    rnd = random.Random(7); out = {k: list(v) for k, v in R.items()}
    combos = [f"{a} {b} {c}".replace("  ", " ").strip() for a, b, c in itertools.product(START, GO, COND)]; combos = [x for x in combos if len(set(x.split())) == len(x.split())]; rnd.shuffle(combos)
    out["advice"] += [c for c in combos if not c.startswith(("is it advisable", "is it fine")) or rnd.random() < 0.5][:70]
    sc = [f"why is {a} {b}" for a, b in itertools.product(SIG, STT)]; rnd.shuffle(sc); out["signal_why"] += sc[:30]
    return augment(out, rnd)


if __name__ == "__main__":
    rows = build()
    with open(os.path.join(HERE, "bench", "everyday_paraphrases.tsv"), "w", encoding="utf-8") as f:
        f.write("# route<TAB>question - written by tools_everyday_paraphrases.py (do not edit by hand)\n")
        for r, qs in rows.items():
            for q in dict.fromkeys(qs): f.write(f"{r}\t{q}\n")
    print(sum(len(v) for v in rows.values()), "examples,", len(rows), "routes")
